/// <summary>
/// PricingAttribute of table <c>CustTable</c> field DefaultDimension.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustTableDefaultDimension extends UPSPricingAttributeCustTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, DefaultDimension);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::Int64);
    CustTable   custTable;

    while select DefaultDimension from custTable
        group by DefaultDimension
    {
        ret.add(custTable.DefaultDimension);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustTable, DefaultDimension));
    qbr.value(queryValue(_value));
}
